                            \pgfpathlineto{\pgfpoint{\pgf@circ@res@right+(\pgf@circ@qfp@pin@shift-\the\pgf@circ@count@a)*\pgf@circ@res@step}{\pgf@circ@res@up+\pgf@circ@res@other}}
                        }{}%
                    \fi
                    \advance\pgf@circ@count@a-1\relax%
                \repeatpgfmathloop
