% Notice that the scale of the symbol should go with the size of the circle, which in the oo-type
% components is linked to the .../height key, which translates in ...res@up and ...res@down
% triangle
\def\pgf@circ@delta#1{
    \pgfscope
        \pgftransformscale{-.015*\ctikzvalof{\ctikzclass/symbol/delta scale}*\pgf@circ@res@up*#1}
        \pgftransformrotate{\ctikzvalof{\ctikzclass/symbol/delta rot}}
        \def\pgfcircmathresult{\expandafter\pgf@circ@stripdecimals\pgf@circ@direction\pgf@nil}
            \pgftransformrotate{-\pgfcircmathresult}
        \pgf@circ@setlinewidth{bipoles}{\pgfstartlinewidth}
        \pgf@circ@set@relative@thickness{symbol/thickness}
        \pgfpathmoveto{\pgfpointpolar{90}{\pgf@circ@res@up}}
        \pgfpathlineto{\pgfpointpolar{-30}{\pgf@circ@res@up}}
        \pgfpathlineto{\pgfpointpolar{-150}{\pgf@circ@res@up}}
        \pgfpathclose
        \pgfusepath{stroke}
    \endpgfscope
}
