%%% fit the ooo-shape to the geo-anchors
\def\pgf@circ@ooo@find@other{
    %% we want the structure of height @up. The (half)height of the drawing is:
    %% h=other*[(1-r)*sin(60)+r] --- so we calculate the other we need to fill the vertical space
    \pgfmathsetlength{\pgf@circ@res@other}{%
        \pgf@circ@res@up/(\circleoffset*sqrt(3)/2+\circlesize)
    }
}
\def\pgf@circ@ooo@anchor@base{
