%%% we find the circle size from the ratio height/width. Change with care.
\pgfcircdeclarebipolescaled{sources}
{
    % we need to save the class scale factor here because is used in plain (not saved) anchors
    \savedmacro{\classscale}{\edef\classscale{\ctikzvalof{\ctikzclass/scale}}}
    %% From the geometry of the component, we know that the width of the drawing is:
    %% w = (1/2*r + 3/2)/((1-r)*sin(60)+r) *(h/2)
    %% we reverse that and we have
    %% r = (3-sqrt(3)*2*w/h)/((2-sqrt(3)*2*w/h-1)
    \savedmacro{\circlesize}{%
        \pgfmathparse{%
            (3-sqrt(3)*2*\ctikzvalof{bipoles/ooosource/width}/\ctikzvalof{bipoles/ooosource/height})/
            ((2-sqrt(3))*2*\ctikzvalof{bipoles/ooosource/width}/\ctikzvalof{bipoles/ooosource/height}-1)
        }
        \edef\circlesize{\pgfmathresult}
    }
    \savedmacro{\circleoffset}{%
        \pgfmathparse{%
            1-(3-sqrt(3)*2*\ctikzvalof{bipoles/ooosource/width}/\ctikzvalof{bipoles/ooosource/height})/
            ((2-sqrt(3))*2*\ctikzvalof{bipoles/ooosource/width}/\ctikzvalof{bipoles/ooosource/height}-1)
        }
        \edef\circleoffset{\pgfmathresult}%
