    % is offset*cos(60) + sqrt(radius^2-(offset*sin(60))^2)
    \anchor{right}{
        \pgf@circ@ooo@anchor@base
        \pgfmathparse{ \circleoffset*0.5 +
            %%the sqrt must be > 0, the circles have to intersect
            %% the abs is to avoid crashes, but the result will be baaaad
            sqrt(abs(pow(\circlesize,2) - pow(\circleoffset*sqrt(3)/2,2)))
