{\ctikzvalof{bipoles/ooosource/height}}
{ooosource}
{\ctikzvalof{bipoles/ooosource/height}}
{\ctikzvalof{bipoles/ooosource/width}}% Notice that only very tied values of height and width will work
{
    %% find the drawing parameter @other:
    \pgf@circ@setlinewidth{bipoles}{\pgfstartlinewidth}
    \pgf@circ@ooo@find@other
    \pgfmathsetlength{\pgf@circ@res@temp}{\circleoffset*\pgf@circ@res@other/4}
    %% move the origin 1/4 of the circle offset
    \pgftransformxshift{\pgf@circ@res@temp}
    % filling
    % left
    \pgfscope
        \pgfpathcircle{\pgfpoint{-\circleoffset\pgf@circ@res@other}{0}}{\circlesize\pgf@circ@res@other}
        \pgf@circ@maybefill
    \endpgfscope
    % up
