        \pgfpathcircle{\pgfpointpolar{60}{\circleoffset\pgf@circ@res@other}}{\circlesize\pgf@circ@res@other}
        \pgf@circ@maybefill
    \endpgfscope
    % down also draw
    \pgfscope
        \pgfpathcircle{\pgfpointpolar{-60}{\circleoffset\pgf@circ@res@other}}{\circlesize\pgf@circ@res@other}
        \pgf@circ@draworfill
    \endpgfscope
    %  drawing
    % left
    \pgfscope
        \pgfpathcircle{\pgfpoint{-\circleoffset\pgf@circ@res@other}{0}}{\circlesize\pgf@circ@res@other}
        \pgfusepath{draw}
    \endpgfscope
    % up
    \pgfscope
        \pgfpathcircle{\pgfpointpolar{60}{\circleoffset\pgf@circ@res@other}}{\circlesize\pgf@circ@res@other}
        \pgfusepath{draw}
    \endpgfscope
% % %     draw inner symbols
% %     primary winding
    \ifpgf@circ@prim@delta
        \pgfscope
            \pgftransformxshift{-\vectorgroupoffset\pgf@circ@res@other}
            \pgftransformrotate{\ctikzvalof{sources/symbol/prim rot}}
            \pgf@circ@delta{\ctikzvalof{bipoles/ooosource/vectorgroupscale}}
        \endpgfscope
    \else\ifpgf@circ@prim@wye
        \pgfscope
            \pgftransformxshift{-\vectorgroupoffset\pgf@circ@res@other}
            \pgftransformrotate{\ctikzvalof{sources/symbol/prim rot}}
            \pgf@circ@wye{\ctikzvalof{bipoles/ooosource/vectorgroupscale}}
        \endpgfscope
        \else\ifpgf@circ@prim@eyw
        \pgfscope
            \pgftransformxshift{-\vectorgroupoffset\pgf@circ@res@other}
            \pgftransformrotate{\ctikzvalof{sources/symbol/prim rot}}
            \pgf@circ@eyw{\ctikzvalof{bipoles/ooosource/vectorgroupscale}}
        \endpgfscope
    \else\ifpgf@circ@prim@zig
        \pgfscope
            \pgftransformxshift{-\vectorgroupoffset\pgf@circ@res@other}
            \pgftransformrotate{\ctikzvalof{sources/symbol/prim rot}}
            \pgf@circ@zig{\ctikzvalof{bipoles/ooosource/vectorgroupscale}}
        \endpgfscope
    \fi\fi\fi\fi
% %     secondary winding
    \ifpgf@circ@sec@delta
        \pgfscope
            \pgftransformshift{\pgfpointpolar{60}{\vectorgroupoffset\pgf@circ@res@other}}
            \pgftransformrotate{\ctikzvalof{sources/symbol/sec rot}}
            \pgf@circ@delta{\ctikzvalof{bipoles/ooosource/vectorgroupscale}}
        \endpgfscope
    \else\ifpgf@circ@sec@wye
        \pgfscope
            \pgftransformshift{\pgfpointpolar{60}{\vectorgroupoffset\pgf@circ@res@other}}
            \pgftransformrotate{\ctikzvalof{sources/symbol/sec rot}}
            \pgf@circ@wye{\ctikzvalof{bipoles/ooosource/vectorgroupscale}}
        \endpgfscope
        \else\ifpgf@circ@sec@eyw
        \pgfscope
            \pgftransformshift{\pgfpointpolar{60}{\vectorgroupoffset\pgf@circ@res@other}}
            \pgftransformrotate{\ctikzvalof{sources/symbol/sec rot}}
            \pgf@circ@eyw{\ctikzvalof{bipoles/ooosource/vectorgroupscale}}
        \endpgfscope
    \else\ifpgf@circ@sec@zig
        \pgfscope
            \pgftransformshift{\pgfpointpolar{60}{\vectorgroupoffset\pgf@circ@res@other}}
            \pgftransformrotate{\ctikzvalof{sources/symbol/sec rot}}
            \pgf@circ@zig{\ctikzvalof{bipoles/ooosource/vectorgroupscale}}
        \endpgfscope
    \fi\fi\fi\fi
% %     tertiary winding
    \ifpgf@circ@tert@delta
        \pgfscope
            \pgftransformshift{\pgfpointpolar{-60}{\vectorgroupoffset\pgf@circ@res@other}}
            \pgftransformrotate{\ctikzvalof{sources/symbol/tert rot}}
            \pgf@circ@delta{\ctikzvalof{bipoles/ooosource/vectorgroupscale}}
        \endpgfscope
    \else\ifpgf@circ@tert@wye
        \pgfscope
            \pgftransformshift{\pgfpointpolar{-60}{\vectorgroupoffset\pgf@circ@res@other}}
            \pgftransformrotate{\ctikzvalof{sources/symbol/tert rot}}
