\def\pgf@circ@direction{0.0}

% swap two coordinates
\def\pgfcirc@swap@coordinates#1#2{%
    coordinate (pgfcirc@tmp@swap) at (#1)
    coordinate (#1) at (#2)
    coordinate (#2) at (pgfcirc@tmp@swap)
}

% Names
\ctikzset{name/.style = { n={#1} } } %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%@@@
\gdef\ctikz@@null{}%
% safety net for re-naming a ctikz path-to
\ctikzset{n/.code = {
    \edef\ctikz@@temp{\ctikzvalof{bipole/name}}%
    \ifx\ctikz@@temp\ctikz@@null\else
        \pgfutil@packagewarning{circuitikz}{path-to component #1 already had a name, ^^J%
        (\ctikz@@temp) expect problems and errors!}%
    \fi
    \pgfkeys{/tikz/circuitikz/bipole/name={#1}}%
}}

% Reflect the node along
\ctikzset{mirrored/.is choice}
\ctikzset{mirror value/.initial=1}
\ctikzset{mirrored/true/.code = {\ctikzsetvalof{mirror value}{-1}} }
\ctikzset{mirrored/false/.code = {\ctikzsetvalof{mirror value}{1}} }
\ctikzset{mirror/.style = {/tikz/circuitikz/mirrored=true}}

% Invert node along path
\ctikzset{inverted/.is choice}
\ctikzset{invert value/.initial=1}
\ctikzset{inverted/true/.code = {\ctikzsetvalof{invert value}{-1}\pgf@circuit@bipole@invertedtrue}}
\ctikzset{inverted/false/.code = {\ctikzsetvalof{invert value}{1}\pgf@circuit@bipole@invertedfalse}}
\ctikzset{invert/.style = {/tikz/circuitikz/inverted=true}}
\newif\ifpgf@circuit@bipole@inverted
\ctikzset{bipole/inverted/.is if=pgf@circuit@bipole@inverted}

\newif\ifpgf@circuit@bipole@voltage@backward
\ctikzset{bipole/voltage/direction/.is choice}
\ctikzset{bipole/voltage/direction/forward/.code={\pgf@circuit@bipole@voltage@backwardfalse}}
\ctikzset{bipole/voltage/direction/backward/.code={\pgf@circuit@bipole@voltage@backwardtrue}}

% Initialize paths
\def\pgfcircresetpath{
    \ctikzset{bipole/name=, bipole/label/name=, bipole/label/position=90, ,bipole/annotation/name=, bipole/annotation/position=-90,
        bipole/inverted=false, bipole/kind=,
        bipole/voltage/direction=backward, bipole/voltage/label/name=, bipole/voltage/position=below,
        bipole/nodes/left=none, bipole/nodes/right=none, bipole/is voltage=false,bipole/is voltageoutsideofsymbol=false,bipole/is strokedsymbol=false,
        bipole/is current=false, bipole/current/label/name=, bipole/current/x position=after,
        bipole/current/y position=above, bipole/current/direction=forward,
        mirrored=false
    }
}

%%
%% implementation of automatic advanced v-i-f labels
%%
\gdef\ctikz@vif@queue{}\newcount\ctikz@vif@count
\newif\ifctikz@hook@set\global\ctikz@hook@setfalse
\def\ctikz@vif@add#1#2#3#4{%add to the queue the macro \#1{nodename}{#2}{#3}{#4}
    \edef\ctikz@vif@@name{\ctikzvalof{bipole/name}}%
    \ifx\ctikz@vif@@name\ctikz@@null
        % we *need* to be sure we have no repeated nodenames
        % this should work well for millions of them.
        \global\advance\ctikz@vif@count by 1 \relax
        \pgfmathrandominteger{\ctikz@vif@@rand}{100}{999}%
        \edef\ctikz@vif@@name{ctikz-vif\the\ctikz@vif@count-\ctikz@vif@@rand}%
        \ctikzset{bipole/name=\ctikz@vif@@name}
    \fi
    % \typeout{NODE2: \ctikzvalof{bipole/name}}
    \edef\ctikz@vif@@temp{%
        \noexpand\pgfutil@g@addto@macro\noexpand\ctikz@vif@queue{%
            \expandafter\noexpand\csname #1\endcsname
            {\ctikz@vif@@name}{#2}{#3}{#4}%
        }%
    }%
    \ctikz@vif@@temp
}
%% set up the hooks if possible and if they are not already set for this picture
\def\ctikz@set@hook{%
    \ifctikz@hook@set
    \else
        \global\ctikz@hook@settrue
        \ifpgfutil@format@is@latex
            \ifctikz@latex@has@hooks
                % we must enable both for circuitikz and tikzpicture (grrr)
                % \typeout{EXECUTE AddToHook ctikzprocessvif}%
                \AddToHookNext{env/tikzpicture/end}{\ctikzprocessvif}%
                \AddToHookNext{env/circuitikz/end}{\ctikzprocessvif}%
            \else
                % \typeout{OLD LaTeX, use "use auto vif"}%
                \pgfutil@packagewarning{circuitikz}{You used automatic advanced v-i-f with a ^^J%
                old LaTeX, you must add "use auto vif" (see manual)}%
            \fi
        \else
            % this is not LaTeX, I will not touch internals
            % \typeout{Not on LaTeX, use "use auto vif"}%
            \pgfutil@packagewarning{circuitikz}{You used automatic advanced v-i-f with a ^^J%
            non-LaTeX format, you must add "use auto vif" (see manual)}%
        \fi
    \fi
}
% manually add hooks for non-LaTeX or older LaTeX. Safe to use always.
\tikzset{use auto vif/.style={execute at end picture={\ctikzprocessvif},
    execute at begin picture={\global\ctikz@hook@settrue}}}
% main v-i-f processing macro. Safe to call always.
\def\ctikzprocessvif{%
    % execute and clear queue
    % \typeout{EXECUTE ctikzprocessvif}%
