% set up plot-type drawing
\def\pgfcirc@setup@plot@filters{%
    \ifpgf@circuit@idealfilter
        \pgfcirc@twoport@draw@linax
    \else
        \pgfcirc@twoport@draw@logax
    \fi
    \edef\@@tmp{\ctikzvalof{blocks/filter plot/relative thickness}}
    \pgfsetlinewidth{\@@tmp\pgflinewidth}
    % ideal filters are "square"
    \ifpgf@circuit@idealfilter\else
        \edef\@@tmp{\ctikzvalof{blocks/filter plot/rounding}}
        \pgfsetcornersarced{\pgfpoint{\@@tmp\pgf@circ@res@step}{\@@tmp\pgf@circ@res@step}}
    \fi
}
% draw a fake lin-lin grid for ideal plot-type filters
\def\pgfcirc@twoport@draw@linax{%
    \pgfscope
        \edef\@@opacity{\ctikzvalof{blocks/filter grid/opacity}}
        \ifdim\@@opacity pt>0pt
            \pgfmathsetmacro{\@@scale}{\pgf@circ@res@step/1cm}
            \pgftransformxscale{\@@scale}
            \pgftransformyscale{\@@scale}
            \def\@@gridx{0.7cm}\def\@@gridy{0.6cm}
            % horizontal lin
            \pgfpathmoveto{\pgfpoint{-\@@gridx}{-\@@gridy}}
            \pgfpathlineto{\pgfpoint{\@@gridx}{-\@@gridy}}
            \pgfpathmoveto{\pgfpoint{-\@@gridx}{-0.5*\@@gridy}}
            \pgfpathlineto{\pgfpoint{\@@gridx}{-0.5*\@@gridy}}
            \pgfpathmoveto{\pgfpoint{-\@@gridx}{0cm}}
            \pgfpathlineto{\pgfpoint{\@@gridx}{0cm}}
            \pgfpathmoveto{\pgfpoint{-\@@gridx}{0.5*\@@gridy}}
            \pgfpathlineto{\pgfpoint{\@@gridx}{0.5*\@@gridy}}
            \pgfpathmoveto{\pgfpoint{-\@@gridx}{\@@gridy}}
            \pgfpathlineto{\pgfpoint{\@@gridx}{\@@gridy}}
            % vertical lin
            \pgfpathmoveto{\pgfpoint{-\@@gridx}{-\@@gridy}}
            \pgfpathlineto{\pgfpoint{-\@@gridx}{\@@gridy}}
            \pgfpathmoveto{\pgfpoint{-0.5*\@@gridx}{-\@@gridy}}
            \pgfpathlineto{\pgfpoint{-0.5*\@@gridx}{\@@gridy}}
            \pgfpathmoveto{\pgfpoint{0cm}{-\@@gridy}}
            \pgfpathlineto{\pgfpoint{0cm}{\@@gridy}}
            \pgfpathmoveto{\pgfpoint{0.5*\@@gridx}{-\@@gridy}}
            \pgfpathlineto{\pgfpoint{0.5*\@@gridx}{\@@gridy}}
            \pgfpathmoveto{\pgfpoint{\@@gridx}{-\@@gridy}}
            \pgfpathlineto{\pgfpoint{\@@gridx}{\@@gridy}}
            %
            \pgf@circ@subset@thickness{blocks/filter grid}
            \pgf@circ@subset@color@dash{blocks/filter grid}
            \pgfsetstrokeopacity{\@@opacity}
            \pgfusepath{draw}
            \ifpgf@circuit@idealfilter@numbers
                \pgftext[right,at={\pgfpoint{-\@@gridx}{-\@@gridy}}]{%
                    \scriptsize\ctikzvalof{ideal filter number low}\kern1pt}
                \pgftext[right,at={\pgfpoint{-\@@gridx}{\@@gridy}}]{%
                    \scriptsize\ctikzvalof{ideal filter number high}\kern1pt}
            \fi
        \fi
    \endpgfscope
}
% draw a fake log-dB(lin) grid for plot-style filters
\def\pgfcirc@twoport@draw@logax{%
    \pgfscope
