            \pgfpathmoveto{\pgfpoint{0.5cm}{-0.8cm}}
            \pgfpathlineto{\pgfpoint{0.5cm}{0.8cm}}
            \pgfpathmoveto{\pgfpoint{0.7cm}{-0.8cm}}
            \pgfpathlineto{\pgfpoint{0.7cm}{0.8cm}}
