\ctikzset{dc symbol/text offset/.initial=6pt}
\tikzset{dc symbol segments/.code={\ctikzset{dc symbol/segments=#1}}}
\ctikzset{dc symbol/relative thickness/.initial=1}
\pgfdeclareshape{dc symbol}{
    \savedmacro{\ctikzclass}{\edef\ctikzclass{misc}}
    \saveddimen{\scaledRlen}{\pgfmathsetlength{\pgf@x}{\ctikzvalof{misc/scale}\pgf@circ@Rlen}}
    \anchor{center}{\pgfpointorigin}
    \savedanchor\northeast{%
        \pgfmathsetlength{\pgf@circ@scaled@Rlen}{\ctikzvalof{misc/scale}\pgf@circ@Rlen}
        \pgf@x=\ctikzvalof{dc symbol/width}\pgf@circ@scaled@Rlen
        \pgf@y=\ctikzvalof{dc symbol/height}\pgf@circ@scaled@Rlen
        \pgf@x=.5\pgf@x\pgf@y=.5\pgf@y
    }
    \savedanchor{\textanchor}{
        % above (add a bit of space)
        \pgfmathsetlength{\pgf@circ@scaled@Rlen}{\ctikzvalof{misc/scale}\pgf@circ@Rlen}
        \pgf@ya=\ctikzvalof{ac symbol/height}\pgf@circ@scaled@Rlen
        \pgfpoint{-.5\wd\pgfnodeparttextbox}{\dimexpr -0.5\dp\pgfnodeparttextbox-.5\ht\pgfnodeparttextbox}
        \advance\pgf@y by \pgf@ya\advance\pgf@y by \ctikzvalof{dc symbol/text offset}
    }
    \anchor{text}{\textanchor}
    \pgfcirc@northeast@symmetric@geoanchors
    \pgf@circ@draw@component{
        \pgfstartlinewidth=\pgflinewidth
        \pgfscope
            \pgf@circ@setcolor
            \pgf@circ@setlinewidth{bipoles}{\pgfstartlinewidth}
            \pgfextractx{\pgf@circ@res@right}{\northeast}
            \pgfextracty{\pgf@circ@res@up}{\northeast}
            \pgf@circ@res@left=-\pgf@circ@res@right
            \pgf@circ@res@down=-\pgf@circ@res@up
            % upper line
            \pgfpathmoveto{\pgfpoint{\pgf@circ@res@left}{\pgf@circ@res@up}}
            \pgfpathlineto{\pgfpoint{\pgf@circ@res@right}{\pgf@circ@res@up}}
            \pgfusepath{draw}
            % lower line
            \edef\@@tmp{\ctikzvalof{dc symbol/relative thickness}}
            \pgfsetlinewidth{\@@tmp\pgflinewidth}
            \edef\@@dashes{\ctikzvalof{dc symbol/segments}}
            \ifnum\@@dashes>1
                \pgfmathsetlength{\pgf@circ@res@other}{2*\pgf@circ@res@right/(2*(\@@dashes-1)+1)}
                \pgf@circ@do@n@hdashes{\@@dashes}{\pgf@circ@res@other}{\pgf@circ@res@left}{\pgf@circ@res@down}
            \else
                \pgfpathmoveto{\pgfpoint{\pgf@circ@res@left}{\pgf@circ@res@down}}
                \pgfpathlineto{\pgfpoint{\pgf@circ@res@right}{\pgf@circ@res@down}}
            \fi
            \pgfusepath{draw}
        \endpgfscope
    }
}
