        \pgf@ya=\ctikzvalof{ac symbol/height}\pgf@circ@scaled@Rlen
        \pgfpoint{-.5\wd\pgfnodeparttextbox}{\dimexpr-0.5\dp\pgfnodeparttextbox-.5\ht\pgfnodeparttextbox}
        \advance\pgf@y by \pgf@ya\advance\pgf@y by \ctikzvalof{ac symbol/text offset}
    }
    \anchor{text}{\textanchor}
    \pgfcirc@northeast@symmetric@geoanchors
    \pgf@circ@draw@component{
        \pgfstartlinewidth=\pgflinewidth
        \pgfscope
            \pgf@circ@setcolor
            \pgf@circ@setlinewidth{bipoles}{\pgfstartlinewidth}
            \pgfextractx{\pgf@circ@res@right}{\northeast}
            \pgfextracty{\pgf@circ@res@up}{\northeast}
            % draw the sine waveform
            \pgfpathmoveto{\pgfpoint{-\pgf@circ@res@right}{0\pgf@circ@res@up}}
            \pgfpathsine{\pgfpoint{.5\pgf@circ@res@right}{\pgf@circ@res@up}}
            \pgfpathcosine{\pgfpoint{.5\pgf@circ@res@right}{-\pgf@circ@res@up}}
            \pgfpathsine{\pgfpoint{.5\pgf@circ@res@right}{-\pgf@circ@res@up}}
            \pgfpathcosine{\pgfpoint{.5\pgf@circ@res@right}{\pgf@circ@res@up}}
            \pgfusepath{draw}
        \endpgfscope
    }
}
