\def\pgfcirc@simplemos@drawbulk#1{%
    \ifpgf@circuit@bpt@drawbulk % added by Burak Kelleci
        \ifpgf@circuit@trans@fdsoi % FDSOI added by Romano Giannetti
            \pgfpathmoveto{\pgfpoint{0.4*\ctikzvalof{tripoles/#1/base width}*\pgf@circ@res@left}
            {\pgf@circ@res@up+\pgf@circ@res@down}}
        \else
            \pgfpathmoveto{\pgfpoint{\ctikzvalof{tripoles/#1/base width}*\pgf@circ@res@left}
            {\pgf@circ@res@up+\pgf@circ@res@down}}
        \fi
        \pgfpathlineto{\pgfpoint{\pgf@circ@res@right+\pgfhorizontaltransformationadjustment*.5*\pgflinewidth}
        {\pgf@circ@res@up+\pgf@circ@res@down}}
