            \else
                \pgfscope
                    \pgfpathmoveto{\pgfpoint
                    {0.4*\ctikzvalof{tripoles/#1/base width}*\pgf@circ@res@left}{1.2*\pgf@circ@res@up+\pgf@circ@res@down}}
