	        \pgftransformshift{\pgfpoint{\pgf@circ@res@right}
        	       {\pgfkeysvalueof{/tikz/circuitikz/tripoles/#1/bodydiode conn}\pgf@circ@res@up}}
   	       	\pgftransformscale{0.5}
        \pgfnode{circ}{center}{}{}{\pgfusepath{fill}}
      \endpgfscope{}
