		 (\tikztostart) node[diamondpole] {} 
	\else 
		\pgfextra{ \def\pgf@temp{empty}  }
		\ifx\pgf@temp\pgf@circ@temp 
			 (\tikztostart) node[ocirc] {} 
		\else 
			\pgfextra{  \def\pgf@temp{full}  }
			\ifx\pgf@temp\pgf@circ@temp 
