			\fi
		\fi
	\fi
	\pgfextra{ \edef\pgf@circ@temp{\ctikzvalof{bipole/nodes/right}} \def\pgf@temp{diamond}  }
	\ifx\pgf@temp\pgf@circ@temp 
		 (\tikztotarget) node[diamondpole] {} 
