            \ifdim\pgf@circ@res@other>0pt
            \pgfscope
                \pgfsetlinewidth{\pgfkeysvalueof{/tikz/circuitikz/multipoles/external pins thickness}\pgflinewidth}
                \pgf@circ@count@a=\numpins%
