    \pgf@circ@oldvoltagedirectiontrue
    \pgf@circ@explicitvdirtrue
    \pgf@circ@fixbatteriestrue}
}
\DeclareOption{EFvoltages}{\AtEndOfPackage{%
    \pgf@circ@oldvoltagedirectionfalse
    \pgf@circ@explicitvdirtrue
