% Wiggly bulbm see https://github.com/circuitikz/circuitikz/issues/845
\pgfcircdeclarebipolescaled{misc}
{}
{\ctikzvalof{bipoles/wbulb/height}}
{wbulb}
{\ctikzvalof{bipoles/wbulb/height}}
{\ctikzvalof{bipoles/wbulb/width}}
{%
    % circles are smaller than the size of the component, for historical reasons.
    % Join the circle to the wires
    \pgfpathmoveto{\pgfpoint{\pgf@circ@res@left}{\pgf@circ@res@zero}}
    \pgfpathlineto{\pgfpoint{0.8\pgf@circ@res@left}{\pgf@circ@res@zero}}
    \pgfpathmoveto{\pgfpoint{\pgf@circ@res@right}{\pgf@circ@res@zero}}
    \pgfpathlineto{\pgfpoint{0.8\pgf@circ@res@right}{\pgf@circ@res@zero}}
    \pgfusepath{draw}
    \pgf@circ@setlinewidth{bipoles}{\pgfstartlinewidth}
    \pgfpathellipse{\pgfpointorigin}{\pgfpoint{0}{0.8\pgf@circ@res@up}}{\pgfpoint{0.8\pgf@circ@res@left}{0}}
    \pgf@circ@draworfill
    \pgfpathmoveto{\pgfpoint{0.8\pgf@circ@res@left}{\pgf@circ@res@zero}}
    % CP: Control Point; FP: Final Point
    \pgfpathcurveto
        {\pgfpoint{0.5\pgf@circ@res@left}{+0pt}}                   % CP1
        {\pgfpoint{0.4\pgf@circ@res@left}{0.6\pgf@circ@res@left}}  % CP2
        {\pgfpoint{+0pt}{+0pt}}                                    % FPA
    \pgfpathcurveto
        {\pgfpoint{.2\pgf@circ@res@right}{.2\pgf@circ@res@right}}  % CP3
        {\pgfpoint{.2\pgf@circ@res@right}{0.6\pgf@circ@res@right}} % CP4
        {\pgfpoint{+0pt}{0.6\pgf@circ@res@right}}                  % FPB
    \pgfpathcurveto
        {\pgfpoint{.2\pgf@circ@res@left}{0.6\pgf@circ@res@right}}  % symmetric to CP4
        {\pgfpoint{.2\pgf@circ@res@left}{.2\pgf@circ@res@right}}   % symmetric to CP3
        {\pgfpoint{+0pt}{+0pt}}                                    % same as FPA
    \pgfpathcurveto
        {\pgfpoint{0.4\pgf@circ@res@right}{0.6\pgf@circ@res@left}} % symmetric to CP2
        {\pgfpoint{0.5\pgf@circ@res@right}{+0pt}}                  % symmetric to CP1
        {\pgfpoint{0.8\pgf@circ@res@right}{\pgf@circ@res@zero}}    % symmetric to FPB
    \pgfusepath{draw}
}%
% neon lamps, suggested by @bogger33 https://github.com/circuitikz/circuitikz/issues/793
