    \pgf@circ@draworfill
    %% leads in
    \pgfsetlinewidth{\pgfstartlinewidth}
    \def\@@w{0.2}\def\@@h{0.6}
    \pgfpathmoveto{\pgfpoint{\pgf@circ@res@left}{0pt}}
    \pgfpathlineto{\pgfpoint{\@@w\pgf@circ@res@left}{0pt}}
    \pgfpathmoveto{\pgfpoint{\pgf@circ@res@right}{0pt}}
